previewCss:
.darma-loader-darma-b15-icicle-drip { --accent: var(--loader-color, #0284c7); --accent-2: var(--loader-secondary-color, #bae6fd); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .92); position: relative; }
.darma-loader-darma-b15-icicle-drip .darma-loader-darma-b15-icicle-drip__ledge { position: absolute; left: 2%; right: 2%; top: 4%; height: 11%; border-radius: 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, var(--accent) 60%, var(--accent-2))); }
.darma-loader-darma-b15-icicle-drip span { position: absolute; top: 13%; width: 14%; background: linear-gradient(var(--accent-2), color-mix(in srgb, var(--accent) 70%, transparent)); clip-path: polygon(0 0, 100% 0, 50% 100%); animation: darma-loader-darma-b15-icicle-drip-ice-melt calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b15-icicle-drip span:nth-of-type(1) { left: 16%; }
.darma-loader-darma-b15-icicle-drip span:nth-of-type(2) { left: 43%; animation-delay: calc(var(--loader-speed, 1s) * .5); }
.darma-loader-darma-b15-icicle-drip span:nth-of-type(3) { left: 70%; animation-delay: calc(var(--loader-speed, 1s) * 1); }
.darma-loader-darma-b15-icicle-drip i { position: absolute; width: 8%; height: 11%; border-radius: 50% 50% 50% 50% / 62% 62% 38% 38%; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b15-icicle-drip-ice-drop calc(var(--loader-speed, 1s) * 1.5) ease-in infinite; }
.darma-loader-darma-b15-icicle-drip i:nth-of-type(1) { left: 19%; top: 48%; }
.darma-loader-darma-b15-icicle-drip i:nth-of-type(2) { left: 73%; top: 44%; animation-delay: calc(var(--loader-speed, 1s) * .75); }
@keyframes darma-loader-darma-b15-icicle-drip-ice-melt { 0%, 100% { height: 46%; opacity: 1; } 50% { height: 24%; opacity: .7; } }
@keyframes darma-loader-darma-b15-icicle-drip-ice-drop { 0% { opacity: 0; transform: translateY(0) scale(.5); } 20% { opacity: 1; } 100% { opacity: 0; transform: translateY(280%) scale(1); } }

